CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name_ar text NOT NULL, name_en text, description_ar text, description_en text, image_url text, active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_public ON public.categories FOR SELECT USING (active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY categories_admin ON public.categories FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.products ADD COLUMN category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, ADD COLUMN archived boolean NOT NULL DEFAULT false, ADD COLUMN featured boolean NOT NULL DEFAULT false, ADD COLUMN best_selling boolean NOT NULL DEFAULT false, ADD COLUMN description_en text;
ALTER TABLE public.product_variants ADD COLUMN sale_price numeric, ADD COLUMN low_stock_threshold integer NOT NULL DEFAULT 5;
ALTER TABLE public.product_variants ADD CONSTRAINT variant_sale_valid CHECK (sale_price IS NULL OR (sale_price>=0 AND price IS NOT NULL AND sale_price<=price)), ADD CONSTRAINT low_stock_valid CHECK (low_stock_threshold>=0);
ALTER TABLE public.shipping_zones ADD COLUMN delivery_info text;
ALTER TABLE public.store_settings ADD COLUMN brand_name text NOT NULL DEFAULT 'KLEANTOP', ADD COLUMN brand_name_ar text NOT NULL DEFAULT 'كلين توب', ADD COLUMN logo_url text, ADD COLUMN favicon_url text, ADD COLUMN tagline text, ADD COLUMN seo_title text, ADD COLUMN seo_description text, ADD COLUMN about_ar text, ADD COLUMN about_en text, ADD COLUMN hero_title_en text, ADD COLUMN hero_subtitle_en text, ADD COLUMN faqs jsonb NOT NULL DEFAULT '[]', ADD COLUMN home_sections jsonb NOT NULL DEFAULT '[{"key":"hero","enabled":true},{"key":"products","enabled":true},{"key":"benefits","enabled":true},{"key":"why","enabled":true},{"key":"wholesale","enabled":true}]', ADD COLUMN restore_stock_on_cancel boolean NOT NULL DEFAULT true;
CREATE TABLE public.coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, kind text NOT NULL DEFAULT 'percent' CHECK (kind IN ('percent','fixed')), amount numeric NOT NULL CHECK(amount>0), minimum_order numeric NOT NULL DEFAULT 0 CHECK(minimum_order>=0), expires_at timestamptz, usage_limit integer CHECK(usage_limit>0), used_count integer NOT NULL DEFAULT 0 CHECK(used_count>=0), product_ids uuid[] NOT NULL DEFAULT '{}', category_ids uuid[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, CHECK(kind<>'percent' OR amount<=100));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coupons TO authenticated; GRANT ALL ON public.coupons TO service_role;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY coupons_admin ON public.coupons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid REFERENCES public.product_variants(id) ON DELETE SET NULL, product_name text NOT NULL, size_label text NOT NULL, delta integer NOT NULL, stock_after integer NOT NULL, reason text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.inventory_movements TO authenticated; GRANT ALL ON public.inventory_movements TO service_role;
ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY inventory_admin_read ON public.inventory_movements FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.orders ADD COLUMN internal_notes text, ADD COLUMN discount numeric NOT NULL DEFAULT 0, ADD COLUMN coupon_code text, ADD COLUMN stock_restored boolean NOT NULL DEFAULT false;
ALTER TABLE public.order_items ADD COLUMN regular_price numeric, ADD COLUMN discount_amount numeric NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.assign_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.inventory_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text; BEGIN IF NEW.stock<0 THEN RAISE EXCEPTION 'NEGATIVE_STOCK'; END IF; IF TG_OP='INSERT' OR NEW.stock<>OLD.stock THEN SELECT name_ar INTO n FROM public.products WHERE id=NEW.product_id; INSERT INTO public.inventory_movements(variant_id,product_name,size_label,delta,stock_after,reason,actor_id) VALUES(NEW.id,coalesce(n,''),NEW.size_label,CASE WHEN TG_OP='INSERT' THEN NEW.stock ELSE NEW.stock-OLD.stock END,NEW.stock,coalesce(nullif(current_setting('app.stock_reason',true),''),'تعديل مخزون من الإدارة'),auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER variant_inventory_audit AFTER INSERT OR UPDATE OF stock ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.inventory_audit();
CREATE OR REPLACE FUNCTION public.adjust_stock(_variant_id uuid,_delta integer,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _delta IS NULL OR _reason IS NULL OR length(trim(_reason))<2 OR length(_reason)>500 THEN RAISE EXCEPTION 'INVALID_ADJUSTMENT'; END IF; PERFORM set_config('app.stock_reason',trim(_reason),true); UPDATE public.product_variants SET stock=stock+_delta WHERE id=_variant_id; IF NOT FOUND THEN RAISE EXCEPTION 'UNAVAILABLE'; END IF; END $$;
REVOKE ALL ON FUNCTION public.adjust_stock(uuid,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.adjust_stock(uuid,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.order_workflow() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i record; BEGIN IF NEW.status NOT IN ('new','confirmed','preparing','shipped','delivered','cancelled') THEN RAISE EXCEPTION 'INVALID_STATUS'; END IF; IF OLD.status='cancelled' AND NEW.status<>'cancelled' THEN RAISE EXCEPTION 'CANCELLED_ORDER_LOCKED'; END IF; IF NEW.status='cancelled' AND OLD.status<>'cancelled' AND NOT OLD.stock_restored AND coalesce((SELECT restore_stock_on_cancel FROM public.store_settings WHERE id=1),false) THEN PERFORM set_config('app.stock_reason','إلغاء الطلب '||OLD.order_number,true); FOR i IN SELECT variant_id,quantity FROM public.order_items WHERE order_id=OLD.id ORDER BY variant_id LOOP UPDATE public.product_variants SET stock=stock+i.quantity WHERE id=i.variant_id; END LOOP; NEW.stock_restored:=true; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_status_workflow BEFORE UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.order_workflow();
CREATE OR REPLACE FUNCTION public.quote_order(_items jsonb,_city text,_coupon text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE it jsonb; v record; q integer; sub numeric:=0; eligible numeric:=0; dis numeric:=0; fee numeric; c public.coupons; s public.store_settings; z public.shipping_zones; has_coupon boolean:=length(trim(coalesce(_coupon,'')))>0; BEGIN IF _items IS NULL OR jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)<1 OR jsonb_array_length(_items)>30 THEN RAISE EXCEPTION 'EMPTY_CART'; END IF; SELECT * INTO s FROM public.store_settings WHERE id=1; SELECT * INTO z FROM public.shipping_zones WHERE city=_city AND active; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_CITY'; END IF; IF has_coupon THEN SELECT * INTO c FROM public.coupons WHERE code=upper(trim(_coupon)); IF NOT FOUND OR NOT c.active OR (c.expires_at IS NOT NULL AND c.expires_at<=now()) OR (c.usage_limit IS NOT NULL AND c.used_count>=c.usage_limit) THEN RAISE EXCEPTION 'INVALID_COUPON'; END IF; END IF; FOR it IN SELECT * FROM jsonb_array_elements(_items) LOOP q:=(it->>'quantity')::integer; IF q IS NULL OR q<1 OR q>100 THEN RAISE EXCEPTION 'INVALID_QTY'; END IF; SELECT pv.id,coalesce(pv.sale_price,pv.price) price,pv.stock,p.id product_id,p.category_id INTO v FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id WHERE pv.id=(it->>'variant_id')::uuid AND pv.active AND p.active AND NOT p.archived; IF NOT FOUND OR v.price IS NULL THEN RAISE EXCEPTION 'UNAVAILABLE'; END IF; IF v.stock<q THEN RAISE EXCEPTION 'OUT_OF_STOCK'; END IF; sub:=sub+v.price*q; IF has_coupon AND ((cardinality(c.product_ids)=0 AND cardinality(c.category_ids)=0) OR v.product_id=ANY(c.product_ids) OR v.category_id=ANY(c.category_ids)) THEN eligible:=eligible+v.price*q; END IF; END LOOP; IF has_coupon THEN IF sub<c.minimum_order OR eligible<=0 THEN RAISE EXCEPTION 'COUPON_NOT_ELIGIBLE'; END IF; dis:=round(least(eligible,CASE WHEN c.kind='percent' THEN eligible*c.amount/100 ELSE c.amount END),2); END IF; fee:=z.fee; IF s.free_shipping_threshold IS NOT NULL AND sub-dis>=s.free_shipping_threshold THEN fee:=0; END IF; RETURN jsonb_build_object('subtotal',sub,'discount',dis,'shipping_fee',fee,'total',sub-dis+coalesce(fee,0)); END $$;
REVOKE ALL ON FUNCTION public.quote_order(jsonb,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.quote_order(jsonb,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.place_order(_name text,_phone text,_city text,_address text,_notes text,_items jsonb,_coupon text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.store_settings; it jsonb; v record; oid uuid; num text; q integer; result jsonb; dis numeric; sub numeric; line_dis numeric; remaining numeric; idx integer:=0; cnt integer; BEGIN SELECT * INTO s FROM public.store_settings WHERE id=1; IF NOT coalesce(s.cod_enabled,false) THEN RAISE EXCEPTION 'COD_DISABLED'; END IF; IF _name IS NULL OR length(trim(_name))<2 OR length(_name)>100 THEN RAISE EXCEPTION 'INVALID_NAME'; END IF; IF _phone IS NULL OR _phone !~ '^01[0125][0-9]{8}$' THEN RAISE EXCEPTION 'INVALID_PHONE'; END IF; IF _address IS NULL OR length(trim(_address))<10 OR length(_address)>500 THEN RAISE EXCEPTION 'INVALID_ADDRESS'; END IF; IF length(_notes)>500 THEN RAISE EXCEPTION 'INVALID_NOTES'; END IF; IF jsonb_typeof(_items)<>'array' THEN RAISE EXCEPTION 'EMPTY_CART'; END IF;
PERFORM 1 FROM public.product_variants WHERE id IN (SELECT (value->>'variant_id')::uuid FROM jsonb_array_elements(_items)) ORDER BY id FOR UPDATE;
IF length(trim(coalesce(_coupon,'')))>0 THEN PERFORM 1 FROM public.coupons WHERE code=upper(trim(_coupon)) FOR UPDATE; END IF;
result:=public.quote_order(_items,_city,_coupon); sub:=(result->>'subtotal')::numeric; dis:=(result->>'discount')::numeric; remaining:=dis; cnt:=jsonb_array_length(_items);
num:='KT-'||to_char(now(),'YYMMDD')||'-'||upper(substr(md5(gen_random_uuid()::text),1,6)); INSERT INTO public.orders(order_number,customer_name,phone,city,address,notes,subtotal,shipping_fee,discount,total,coupon_code) VALUES(num,trim(_name),_phone,_city,trim(_address),nullif(trim(_notes),''),sub,(result->>'shipping_fee')::numeric,dis,(result->>'total')::numeric,nullif(upper(trim(_coupon)),'')) RETURNING id INTO oid;
PERFORM set_config('app.stock_reason','طلب '||num,true);
FOR it IN SELECT * FROM jsonb_array_elements(_items) LOOP q:=(it->>'quantity')::integer; SELECT pv.*,p.name_ar INTO v FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id WHERE pv.id=(it->>'variant_id')::uuid; IF v.stock<q THEN RAISE EXCEPTION 'OUT_OF_STOCK'; END IF; UPDATE public.product_variants SET stock=stock-q WHERE id=v.id; idx:=idx+1; line_dis:=CASE WHEN idx=cnt THEN remaining ELSE round(dis*(coalesce(v.sale_price,v.price)*q)/nullif(sub,0),2) END; remaining:=remaining-line_dis; INSERT INTO public.order_items(order_id,variant_id,product_name,size_label,unit_price,regular_price,discount_amount,quantity) VALUES(oid,v.id,v.name_ar,v.size_label,coalesce(v.sale_price,v.price),v.price,line_dis,q); END LOOP;
IF dis>0 THEN UPDATE public.coupons SET used_count=used_count+1 WHERE code=upper(trim(_coupon)); END IF; RETURN result||jsonb_build_object('order_number',num); END $$;
REVOKE ALL ON FUNCTION public.place_order(text,text,text,text,text,jsonb,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.place_order(text,text,text,text,text,jsonb,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.place_order(_name text,_phone text,_city text,_address text,_notes text,_items jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.place_order(_name,_phone,_city,_address,_notes,_items,''); $$;